import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        long mod = sc.nextLong();

        long[][] C = new long[n + 1][n + 1];
        long[] w = new long[n + 1];
        long[] dp = new long[n + 1];

        long[][] dp2 = new long[n + 2][m + 1];
        long[][] w2 = new long[n + 2][m + 1];

        // Compute binomial coefficients
        C[0][0] = 1;
        for (int i = 1; i <= n; ++i) {
            C[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod;
            }
        }

        // Compute w array
        w[0] = 1;
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= i; ++j) {
                long val = C[i - 1][j - 1] * w[j - 1] % mod * w[i - j] % mod;
                w[i] = (w[i] + val * (i + 1)) % mod;

                long sum_part = (dp[j - 1] * w[i - j] + w[j - 1] * dp[i - j]) % mod;
                long comb_part = (long)( (i - j) * (i - j + 1) / 2 + j * (j - 1) / 2 );

                long total = (C[i - 1][j - 1] * sum_part) % mod * (i + 1) % mod;
                total = (total + val * comb_part) % mod;
                dp[i] = (dp[i] + total) % mod;
            }
        }

        // Compute w2 and dp2 arrays
        w2[0][0] = 1;
        for (int i = 1; i <= n + 1; ++i) {
            for (int k = 0; k <= m; ++k) {
                for (int j = 1; j <= Math.min(i - 1, k); ++j) {
                    int pi = i - j - 1;
                    int pk = k - j;
                    long c = C[k][j];

                    w2[i][k] = (w2[i][k] + c * w2[pi][pk] % mod * w[j]) % mod;

                    long t1 = c * w2[pi][pk] % mod * dp[j] % mod;
                    long t2 = c * dp2[pi][pk] % mod * w[j] % mod;
                    dp2[i][k] = (dp2[i][k] + t1 + t2) % mod;
                }
            }
            for (int j = 0; j <= m; ++j) {
                dp2[i][j] = (dp2[i][j] + dp2[i - 1][j]) % mod;
                w2[i][j] = (w2[i][j] + w2[i - 1][j]) % mod;
            }
        }

        System.out.println(dp2[n + 1][m]);
        sc.close();
    }
}
